import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
const pages=await(await fetch('http://127.0.0.1:9222/json')).json();const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
let sequence=0;const pending=new Map();ws.onmessage=({data})=>{const m=JSON.parse(data);if(pending.has(m.id)){pending.get(m.id)(m.result);pending.delete(m.id);}};
const send=(method,params={})=>new Promise(r=>{pending.set(++sequence,r);ws.send(JSON.stringify({id:sequence,method,params}));});
const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
await fs.mkdir('docs/qa/dialogos-normalizados',{recursive:true});
try{
 await send('Page.enable');
 for(const [name,width,height,mobile]of [['desktop',960,540,false],['android',390,844,true],['paisagem',844,390,true]]){
  await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});await send('Emulation.setUserAgentOverride',{userAgent:mobile?'Mozilla/5.0 (Linux; Android 14) Mobile':'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)'});
  await send('Page.navigate',{url:'http://127.0.0.1:3001/tests/toy-room-arena.html?dialogos='+Date.now()});await new Promise(r=>setTimeout(r,350));
  for(let i=0;i<200;i++){if(await evaluate('document.body.dataset.ready==="true"&&Boolean(window.arenaTest)'))break;await new Promise(r=>setTimeout(r,100));}
  const result=await evaluate(`(async()=>{
   arenaTest.pause();const room=arenaTest.room;room.introAlpha=0;room.introBannerTimer=0;
   const {dialogueRenderer}=await import('/src/js/ui/DialogueRenderer.js');const {getMobileUILayout}=await import('/src/js/ui/MobileUILayout.js');
   const portraits=[],boxes=[];const render=dialogueRenderer.renderDialogue,portrait=dialogueRenderer.drawPortrait,round=room.ctx.roundRect;let active=false;
   dialogueRenderer.renderDialogue=function(...args){active=true;try{return render.apply(this,args);}finally{active=false;}};
   dialogueRenderer.drawPortrait=function(ctx,speaker,...args){portraits.push(speaker);return portrait.call(this,ctx,speaker,...args);};
   room.ctx.roundRect=function(...args){if(active)boxes.push(args);return round.apply(this,args);};
   try{for(const elapsed of [0,120]){Object.assign(room.story.state,{investigationStage:'COLLECTING',returnDialogueElapsed:elapsed});const saved=JSON.stringify(room.story.snapshot());room.render();if(JSON.stringify(room.story.snapshot())!==saved)throw Error('Render alterou save.');}
    const layout=getMobileUILayout(room.canvas);return {portraits,boxes,controlTop:layout.action.y-layout.action.radius,mobile:room.mobilePresentation};
   }finally{dialogueRenderer.renderDialogue=render;dialogueRenderer.drawPortrait=portrait;room.ctx.roundRect=round;}
  })()`);
  assert.deepEqual(result.portraits,['fairy','baby']);for(const box of [result.boxes[0],result.boxes[2]]){assert.ok(box[0]>=0&&box[0]+box[2]<=width);if(result.mobile)assert.ok(box[1]+box[3]<result.controlTop,'Diálogo não cobre controles.');else assert.ok(box[1]>height*.6,'Caixa fica na faixa inferior.');}
  const shot=await send('Page.captureScreenshot',{format:'png'});const bytes=Buffer.from(shot.data,'base64');await fs.writeFile('docs/qa/dialogos-normalizados/'+name+'.png',bytes);await fs.writeFile('/tmp/legendgirl-dialogos-'+name+'.png',bytes);
  await fs.writeFile('docs/qa/dialogos-normalizados/'+name+'.json',JSON.stringify(result));console.log('APROVADO: '+name+' — retratos, caixa inferior, controles e persistência.');
 }
}finally{ws.close();}
